    intros fx' j vals R M VM A1 cr HL P0 P48 P3 P4 P5 P84 P101 Hj HR HK HBR HBUF HH hs Hhs31 Hhsok HAS.
    assert (Hhs32 : (Z.of_nat (length (DRV_ATEXIT :: hs)) <= 32)%Z) by (cbn [length]; lia).
