      destruct (Nat.eq_dec i 8) as [->|N8]. { change (nth 8 srY0 (ELit 0)) with (ELit 0). exact G8. }
      destruct (Nat.eq_dec i 10) as [->|N10]. { change (nth 10 srY0 (ELit 0)) with (ELit 0). exact G10. }
