  Lemma last_S : forall j, SSP 1 j (E j).
  Proof.
    intros j. unfold SSP.
    intros fx' vals R M VM A1 PTR OWN LB cr g (HL & P0 & P1 & P2 & P3 & P4 & P5 & P48 & P70 & P73 & P79 & P81 & P82 & P83)
